### 核心服务契约与接口定义（并发控制与原子操作）

1. **存储服务接口 (`IStorageService`)**：
```typescript
export interface SaveNoteResult {
  success: boolean;
  conflict?: boolean;
  currentNote?: Note;
}

export interface IStorageService {
  init(): Promise<void>;
  close(): Promise<void>;

  // 便签 CRUD 与并发控制
  getNoteById(id: string): Promise<Note | null>;
  listNotes(filter?: { status?: NoteStatus; tags?: string[] }): Promise<Note[]>;
  saveNote(note: Note, expectedRevision?: number): Promise<SaveNoteResult>; // expectedRevision 校验，若 dbNote.revision !== expectedRevision 则返回 conflict: true 与 dbNote

  // 生命周期流转（回收区与归档）
  trashNote(id: string): Promise<void>;                     // 记录 previousStatus 与 trashedAt
  restoreNote(id: string): Promise<Note>;                   // 恢复至 previousStatus，清除 trashedAt
  unarchiveNote(id: string): Promise<Note>;                 // 从已归档恢复至 active
  hardDeleteNote(id: string): Promise<void>;                // 物理彻底删除
  listExpiredTrashedNotes(retentionDays?: number): Promise<Note[]>; // 筛选超 7 天便签
  purgeExpiredTrashedNotes(retentionDays?: number): Promise<{ purgedCount: number }>; // 单原子事务批量清空已超期便签
  emptyTrash(): Promise<{ purgedCount: number }>;           // 单原子事务清空回收区

  // 批量操作（事务保证）
  batchUpdateTags(oldTag: string, newTag: string): Promise<{ affectedCount: number }>;
  batchImportNotes(notes: Note[], mode: 'merge' | 'overwrite'): Promise<{ inserted: number; updated: number }>;
  clearAllData(): Promise<void>;

  // 元数据与配额
  getMeta<T>(key: string): Promise<T | null>;
  setMeta<T>(key: string, value: T): Promise<void>;
  getStorageQuota(): Promise<{ usage: number; quota: number; percentUsed: number }>;
}
```

